-- Hyprland config, Lua format.
--
-- Hyprland 0.57 DELETED src/config/legacy/, so hyprland.conf is no longer read at
-- all -- it gets fed straight to Lua and dies on the first '#'. This file replaces
-- it. hyprland.conf is kept beside it for one release as a reference and is now
-- inert: Hyprland resolves hyprland.lua first and only falls back when it is absent.
--
-- Shared byte-identically by every machine. Anything describing ONE desk's physical
-- displays lives in monitors.lua, generated by home-manager from
-- profiles.desktop-hyprland.monitors in the nix-config's hosts/<host>.nix.

hl.config({ debug = { disable_logs = false } })

------------------------------------------------------------------ monitors ----
hl.monitor({ output = "", mode = "highres", position = "auto", scale = 1 })

-- Sourced AFTER the catch-all so host rules win, and re-read on every
-- `hyprctl reload` - which is what keeps SUPER+W from reverting them.
-- Always exists, empty on hosts that declare nothing.
pcall(dofile, os.getenv("HOME") .. "/.config/hypr/monitors.lua")

-------------------------------------------------------------------- colours ----
-- pywal regenerates this on every wallpaper change; change_wallpaper.sh then
-- reloads Hyprland. Defaults keep the config valid before pywal has ever run.
local ok, wal = pcall(dofile, os.getenv("HOME") .. "/.cache/wal/colors-hyprland.lua")
local c = (ok and type(wal) == "table") and wal or {}
local color1     = c.color1 or "rgb(6E908B)"
local color2     = c.color2 or "rgb(95AD9E)"
local background = c.background or "rgb(091b1e)"

hl.env("XCURSOR_SIZE", "16")

---------------------------------------------------------------------- input ----
hl.config({
    input = {
        kb_layout    = "us",
        follow_mouse = 1,
        sensitivity  = 0, -- -1.0 - 1.0, 0 means no modification
        touchpad     = { natural_scroll = false },
    },

    general = {
        gaps_in     = 3,
        gaps_out    = 15,
        border_size = 1,
        col         = {
            active_border   = { colors = { color1, color1, color2 }, angle = 45 },
            inactive_border = background,
        },
        layout = "dwindle",
    },

    decoration = {
        rounding         = 10,
        active_opacity   = 1.0,
        inactive_opacity = 0.8,
        blur             = { size = 5, passes = 4, new_optimizations = true },
        shadow           = { enabled = true, range = 4, render_power = 3, color = "rgba(1a1a1aee)" },
    },

    -- dwindle:pseudotile was dropped in 0.56; pseudotiling has no master switch
    -- any more, the SUPER+P dispatcher below is all that is needed.
    dwindle = { preserve_split = true },
    master  = { new_status = "master" },

    -- 0.56 replaced the gestures:workspace_swipe bool with a "gesture" keyword and
    -- made gestures opt-in, so declaring none keeps trackpad swiping off. The
    -- touchscreen is a separate path the rework left alone: onTouchDown gates purely
    -- on this bool. EDGE swipe only - the finger must land within gaps_out +
    -- border_size (16px) of the left or right edge; from the middle nothing happens.
    gestures = { workspace_swipe_touch = true },

    cursor = { no_hardware_cursors = true },

    misc = { disable_hyprland_logo = true, disable_splash_rendering = true },
})

-- Deliberately NO AQ_DRM_DEVICES anywhere. It is a whitelist - aquamarine drops
-- every card not named in it - and /dev/dri/cardN numbering is not stable: evdi can
-- claim a lower number than the PCI GPUs, which silently dropped the nvidia card on
-- one boot. Unset, aquamarine moves the GPU with the most built-in panels to the
-- front; here that is i915, which is exactly the Intel-primary arrangement the
-- DisplayLink dock needs. See aquamarine#169 (fix #279, merged 2026-10-30 - but
-- measured WORSE on this host, see the nix-config's programs.hyprland comment).

----------------------------------------------------------------- animations ----
hl.curve("myBezier", { type = "bezier", points = { { 0.05, 0.9 }, { 0.1, 1.05 } } })
hl.curve("linear",   { type = "bezier", points = { { 0.0, 0.0 },  { 1.0, 1.0 } } })

hl.animation({ leaf = "windows",     enabled = true, speed = 7,  bezier = "myBezier" })
hl.animation({ leaf = "windowsOut",  enabled = true, speed = 7,  bezier = "default", style = "popin 80%" })
hl.animation({ leaf = "border",      enabled = true, speed = 10, bezier = "default" })
hl.animation({ leaf = "borderangle", enabled = true, speed = 50, bezier = "linear", style = "loop" })
hl.animation({ leaf = "fade",        enabled = true, speed = 7,  bezier = "default" })
hl.animation({ leaf = "workspaces",  enabled = true, speed = 2,  bezier = "default" })

---------------------------------------------------------------------- rules ----
hl.layer_rule({ name = "no-anim-hyprpicker", match = { namespace = "hyprpicker" }, no_anim = true })
hl.layer_rule({ name = "no-anim-selection",  match = { namespace = "selection" },  no_anim = true })

hl.window_rule({ name = "ws2-chromium",  match = { class = "^(chromium-browser)$" }, workspace = "2" })
hl.window_rule({ name = "ws5-discord",   match = { class = "^(discord)$" },          workspace = "5" })
hl.window_rule({ name = "ws5-thunderbird", match = { class = "^(thunderbird)$" },    workspace = "5" })
-- Matched on class, not title: the title rule this replaces only fired for
-- "Spotify Premium", so a free account (or a window whose title was not set yet)
-- landed wherever happened to be focused. Class is set before the surface maps.
hl.window_rule({ name = "ws6-spotify",   match = { class = "^(spotify)$" },   workspace = "6" })
hl.window_rule({ name = "ws7-obsidian",  match = { class = "^(obsidian)$" },  workspace = "7" })
hl.window_rule({ name = "ws8-virtviewer", match = { class = "^(virt-viewer)$" }, workspace = "8" })
hl.window_rule({ name = "float-floatterm", match = { class = "^(floatterm)$" }, float = true })

---------------------------------------------------------------------- binds ----
local mainMod = "SUPER"

hl.bind(mainMod .. " + RETURN", hl.dsp.exec_cmd("kitty"))
hl.bind(mainMod .. " + Q",      hl.dsp.window.close())
hl.bind(mainMod .. " + M",      hl.dsp.exit())
hl.bind(mainMod .. " + E",      hl.dsp.exec_cmd("dolphin"))
hl.bind(mainMod .. " + V",      hl.dsp.window.float({ action = "toggle" }))
-- The ags launcher rather than rofi: rofi binds no wl_touch and holds a pointer
-- grab while open, so on the tablet nothing else can be touched until it closes.
hl.bind(mainMod .. " + R",      hl.dsp.exec_cmd("ags request -i ryzzen-shell toggle-launcher"))
hl.bind(mainMod .. " + P",      hl.dsp.window.pseudo())
hl.bind(mainMod .. " + PRINT",  hl.dsp.exec_cmd('grim -g "$(slurp)" - | swappy -f -'))
hl.bind(mainMod .. " + F",      hl.dsp.window.fullscreen())
-- No -e/--ignore-empty-password on purpose: an empty Enter has to reach PAM,
-- otherwise pam_u2f never runs and the YubiKey cannot unlock the screen without
-- typing something first (nix-config: modules/nixos/yubikey-login.nix).
hl.bind(mainMod .. " + L",      hl.dsp.exec_cmd('swaylock --image "$(< "${HOME}/.cache/wal/wal")"'))

-- Blank every monitor / bring them all back, on one key.
--
-- locked = true is the old `bindl` flag: it is what lets this fire while a session
-- lock is up, so it still works after SUPER+L. A plain bind is suppressed for as
-- long as swaylock holds the lock, which is exactly when you want it.
--
-- Deliberately NOT "dpms toggle": toggle flips each monitor against its OWN state,
-- so if the states have drifted apart it inverts them instead of unifying them.
-- The test is "is ANY enabled monitor still on?" -> force them all off, else all on.
-- `hyprctl monitors` lists only enabled outputs, so a disabled panel is ignored.
hl.bind(mainMod .. " + O",
    hl.dsp.exec_cmd('if hyprctl monitors | grep -q "dpmsStatus: 1"; then hyprctl dispatch dpms off; else hyprctl dispatch dpms on; fi'),
    { locked = true })

hl.bind(mainMod .. " + W", hl.dsp.exec_cmd("~/.config/ressources/scripts/change_wallpaper.sh"))
hl.bind(mainMod .. " + D", hl.dsp.exec_cmd("thunar"))

-- Move focus
for key, dir in pairs({ left = "left", right = "right", up = "up", down = "down" }) do
    hl.bind(mainMod .. " + " .. key, hl.dsp.focus({ direction = dir }))
end

-- Minimise to a per-key special workspace with SUPER + [F1-F12].
--
-- One key, five dispatchers in order. A dispatcher is userdata, not a function:
-- calling it inside a function body only builds one and throws it away, so each has
-- to go through hl.dispatch(). hl.bind takes a single dispatcher or a lua function -
-- a list of dispatchers is rejected.
local magicbags = { "magicbag", "magicbag1", "magicbag2", "magicbag3", "magicbag4", "magicbag5",
                    "magicbag6", "magicbag7", "magicbag8", "magicbag9", "magicbag0", "magicbag10" }
for i, bag in ipairs(magicbags) do
    hl.bind(mainMod .. " + F" .. i, function()
        hl.dispatch(hl.dsp.workspace.toggle_special(bag))
        hl.dispatch(hl.dsp.window.move({ workspace = "+0" }))
        hl.dispatch(hl.dsp.workspace.toggle_special(bag))
        hl.dispatch(hl.dsp.window.move({ workspace = "special:" .. bag }))
        hl.dispatch(hl.dsp.workspace.toggle_special(bag))
    end)
end

-- Workspaces 1-10 on SUPER + [1-9,0], move window with SHIFT
for i = 1, 10 do
    local key = (i == 10) and "0" or tostring(i)
    hl.bind(mainMod .. " + " .. key,           hl.dsp.focus({ workspace = i }))
    hl.bind(mainMod .. " + SHIFT + " .. key,   hl.dsp.window.move({ workspace = i }))
end

-- Move active workspace to monitor
hl.bind(mainMod .. " + J", hl.dsp.workspace.move({ monitor = "r" }))
hl.bind(mainMod .. " + K", hl.dsp.workspace.move({ monitor = "l" }))

-- Scroll through existing workspaces
hl.bind(mainMod .. " + mouse_down", hl.dsp.focus({ workspace = "e+1" }))
hl.bind(mainMod .. " + mouse_up",   hl.dsp.focus({ workspace = "e-1" }))

-- Move/resize with SUPER + LMB/RMB drag (the old bindm)
hl.bind(mainMod .. " + mouse:272", hl.dsp.window.drag(),   { mouse = true })
hl.bind(mainMod .. " + mouse:273", hl.dsp.window.resize(), { mouse = true })

------------------------------------------------------------------ autostart ----
-- `uwsm finalize` completes the uwsm handshake from inside the compositor: it
-- exports WAYLAND_DISPLAY, DISPLAY and everything in UWSM_FINALIZE_VARNAMES into the
-- systemd and dbus activation environments, then sends the readiness notification
-- that flips the compositor unit active. Only then does graphical-session.target come
-- up, which is what starts ags, udiskie and the tablet's units.
--
-- The extra names are not optional: finalize exports WAYLAND_DISPLAY, DISPLAY and
-- UWSM_FINALIZE_VARNAMES only, and the hand-rolled import-environment this replaced
-- also carried PATH, XDG_DATA_DIRS and QT_QPA_PLATFORMTHEME. Without them ags loses
-- hyprctl from its PATH and cannot see .desktop entries.
--
-- Do not reintroduce `systemctl --user start` lines here: they ran ahead of the
-- environment rather than after it, which is how ags died five times in one second
-- on "Failed to open display" and stayed dead for the session.
--
-- swaync is deliberately absent: it ships a D-Bus service file, so the first
-- notification starts it on its own. Launching it here only adds a second instance
-- that races the activated one for the bus name.
hl.on("hyprland.start", function()
    hl.exec_cmd("uwsm finalize PATH XDG_DATA_DIRS QT_QPA_PLATFORMTHEME")
    -- "swww init" is deprecated in swww 0.9; swww-daemon is the supported entry point.
    hl.exec_cmd("swww-daemon")
    hl.exec_cmd("~/.config/ressources/scripts/change_wallpaper.sh")
    -- Outputs that appear after login get swww's stale per-output cache, so the
    -- screens drift apart. This re-applies the wallpaper on every monitoradded.
    hl.exec_cmd("~/.config/ressources/scripts/wallpaper_watch.sh")
end)
